<?php
declare(strict_types=1);$rows=[];$total=0;if(is_file(__DIR__.'/config.local.php')){require __DIR__.'/config.local.php';try{$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$rows=$pdo->query("SELECT t.id,CONCAT(o.city,' → ',d.city) route,DATE_FORMAT(t.departure_at,'%d/%m/%Y %H:%i') departure,COUNT(DISTINCT tk.id) sold,COUNT(DISTINCT ts.id) capacity,COALESCE(SUM(tk.price),0) income FROM trips t JOIN routes r ON r.id=t.route_id JOIN terminals o ON o.id=r.origin_id JOIN terminals d ON d.id=r.destination_id JOIN trip_seats ts ON ts.trip_id=t.id LEFT JOIN tickets tk ON tk.trip_seat_id=ts.id AND tk.status IN ('valid','boarded') GROUP BY t.id ORDER BY t.departure_at")->fetchAll();$total=0;foreach($rows as $r)$total+=(float)$r['income'];}catch(Throwable $e){}}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes · Ruta Norte</title><link rel="stylesheet" href="assets/app.css?v=20261028"></head><body><header class="top"><a class="brand" href="index.php"><span class="brand-icon">RN</span> RUTA<span>NORTE</span></a><nav><a href="index.php">Buscar viajes</a><a href="manifiesto.php">Embarque</a><a class="active" href="reportes.php">Reportes</a><a href="pasajeros.php">Pasajeros</a></nav><div class="user"><span class="avatar">AD</span><span>Administración<small>Reportes</small></span></div></header><main class="subpage"><div class="eyebrow">ANÁLISIS · VENTAS</div><h1>Ocupación e ingresos</h1><p class="muted">Resumen de ocupación y ventas por viaje.</p><div class="metrics"><article><small>VIAJES PROGRAMADOS</small><b><?=count($rows)?></b></article><article><small>BOLETOS VENDIDOS</small><b><?=array_sum(array_column($rows,'sold'))?></b></article><article><small>INGRESOS REGISTRADOS</small><b>S/ <?=number_format((float)$total,2)?></b></article></div><div class="manifest"><div class="report-row"><b>Ruta</b><b>Salida</b><b>Ocupación</b><b>Ingresos</b></div><?php foreach($rows as $r):?><div class="report-row"><span><?=htmlspecialchars($r['route'])?></span><span><?=htmlspecialchars($r['departure'])?></span><span><?=((int)$r['capacity']?round(100*$r['sold']/$r['capacity']):0)?>% · <?=$r['sold']?>/<?=$r['capacity']?></span><b>S/ <?=number_format((float)$r['income'],2)?></b></div><?php endforeach;?><?php if(!$rows):?><div class="empty">Configura la base de datos para mostrar los reportes.</div><?php endif;?></div></main></body></html>

